package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Color;
import org.bukkit.Particle;
import org.bukkit.entity.Creeper;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class NervousPoweredCreeperBehaviour implements CompiledBehaviour {
    private static final Particle DUST = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dust");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final PotionEffectType SPEED = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:speed");

    private final MobContext context;

    private Cooldown cooldown;

    public NervousPoweredCreeperBehaviour(MobContext context) {
        this.context = context;
        // node #27 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onNightEnd() {
        // node #5 mob.night_end
        // node #7 creeper.mutate
        // node #6 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        self.setMaxFuseTicks(0);
        // node #8 creeper.ignite
        self.ignite();
        // node #9
    }

    @Override
    public void onSpawn() {
        // node #20 mob.spawn
        // node #22 creeper.mutate
        // node #21 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        self.setPowered(true);
        // node #23 creeper.mutate
        self.setMaxFuseTicks(1);
        // node #24 world.spawn_particle
        BukkitRuntime.particles(this.context, self.getWorld(), DUST, self.getEyeLocation(), 10, 1.5d, 1.0d, 1.5d, new Particle.DustOptions(Color.fromRGB(255, 0, 0), 4.0f));
        // node #25
    }

    @Override
    public void onTick() {
        // node #33 mob.tick
        // node #36 flow.branch
        // node #34 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(30000.0d));
        if (!cooldown) return;
        // node #35 living_entity.apply_effect
        ((Creeper) this.context.entity()).addPotionEffect(new PotionEffect(SPEED, (int) (60.0d * 20), 2, false, false));
        // node #37
    }
}
